CREATE TABLE IF NOT EXISTS gis_ward_authority_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL UNIQUE, authority_name text NOT NULL, evidence_scope text NOT NULL, source_url text NOT NULL, authority_level text NOT NULL DEFAULT 'CANDIDATE', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_ward_evidence_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL, source_id uuid NOT NULL REFERENCES gis_ward_authority_sources(id), evidence_reference text NOT NULL, match_type text NOT NULL, confidence numeric(5,4), status text NOT NULL DEFAULT 'PENDING_REVIEW', created_at timestamptz NOT NULL DEFAULT now());